import {
  ChangeDetectionStrategy,
  Component,
  Signal,
  TemplateRef,
  ViewEncapsulation,
  booleanAttribute,
  input,
  numberAttribute,
  output
} from '@angular/core';

import type { Chart, Event, Types } from '@antv/g2';
import { format } from 'date-fns';

import { G2BaseComponent, G2Time } from '@delon/chart/core';
import { toDate } from '@delon/util/date-time';
import { NzStringTemplateOutletDirective } from 'ng-zorro-antd/core/outlet';
import type { NzSafeAny } from 'ng-zorro-antd/core/types';
import { NzSkeletonComponent } from 'ng-zorro-antd/skeleton';

/**
 * 数据
 *
 * 注：根据 `maxAxis` 值传递指标数据
 */
export interface G2TimelineData {
  /**
   * 时间值
   */
  time?: G2Time;
  /** 指标1数据 */
  y1: number;
  /** 指标2数据 */
  y2?: number;
  /** 指标3数据 */
  y3?: number;
  /** 指标4数据 */
  y4?: number;
  /** 指标5数据 */
  y5?: number;
  [key: string]: NzSafeAny;
}

export interface G2TimelineMap {
  /** 指标1 */
  y1: string;
  /** 指标 */
  y2?: string;
  /** 指标3 */
  y3?: string;
  /** 指标4 */
  y4?: string;
  /** 指标5 */
  y5?: string;

  [key: string]: string | undefined;
}

export interface G2TimelineClickItem {
  item: G2TimelineData;
  ev: Event;
}

@Component({
  selector: 'g2-timeline',
  exportAs: 'g2Timeline',
  template: `
    <ng-container *nzStringTemplateOutlet="title()">
      <h4>{{ title() }}</h4>
    </ng-container>
    @if (!loaded()) {
      <nz-skeleton />
    }
    <div #container></div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NzStringTemplateOutletDirective, NzSkeletonComponent]
})
export class G2TimelineComponent extends G2BaseComponent {
  // #region fields

  readonly title = input<string | TemplateRef<void> | null>();
  readonly maxAxis = input(2, { transform: numberAttribute });
  readonly data = input<G2TimelineData[]>([]);
  readonly titleMap = input<G2TimelineMap | null>();
  readonly colorMap = input<G2TimelineMap>({
    y1: '#5B8FF9',
    y2: '#5AD8A6',
    y3: '#5D7092',
    y4: '#F6BD16',
    y5: '#E86452'
  });
  readonly mask = input<string>('HH:mm');
  readonly maskSlider = input<string>('HH:mm');
  readonly position = input<'top' | 'right' | 'bottom' | 'left'>('top');
  readonly height = input(450, { transform: numberAttribute });
  readonly padding = input<number[]>([40, 8, 64, 40]);
  readonly borderWidth = input(2, { transform: numberAttribute });
  readonly slider = input(true, { transform: booleanAttribute });
  readonly clickItem = output<G2TimelineClickItem>();

  // #endregion

  /** 等价旧 onlyChangeData：除 titleMap 外，其余输入变更都只需更新数据 */
  protected override isDataOnly(changed: ReadonlyArray<Signal<unknown>>): boolean {
    return !changed.includes(this.titleMap);
  }

  install(): void {
    const { node, height, padding, slider, maxAxis, theme, maskSlider } = this;
    const chart: Chart = (this._chart = new this.winG2.Chart({
      container: node().nativeElement,
      autoFit: true,
      height: height(),
      padding: padding(),
      theme: theme()
    }));
    chart.axis('time', { title: null });
    chart.axis('y1', { title: null });
    for (let i = 2; i <= maxAxis(); i++) {
      chart.axis(`y${i}`, false);
    }

    chart.line().position('time*y1');
    for (let i = 2; i <= maxAxis(); i++) {
      chart.line().position(`time*y${i}`);
    }

    chart.tooltip({
      showCrosshairs: true,
      shared: true
    });

    const sliderPadding = { ...[], ...padding() };
    sliderPadding[0] = 0;
    if (slider()) {
      chart.option('slider', {
        height: 26,
        start: 0,
        end: 1,
        trendCfg: {
          isArea: false
        },
        minLimit: 2,
        formatter: (val: Date) => format(val, maskSlider())
      });
    }

    chart.on(`plot:click`, (ev: Event) => {
      const records = this._chart!.getSnapRecords({ x: ev.x, y: ev.y });
      this.clickItem.emit({ item: records[0]._origin, ev });
    });

    chart.on(`legend-item:click`, (ev: Event) => {
      const item = ev?.target?.get('delegateObject').item;
      const id = item?.id;
      const line = chart.geometries.find(w => w.getAttribute('position').getFields()[1] === id);
      if (line) {
        line.changeVisible(!item.unchecked);
      }
    });

    this.ready.emit(chart);

    this.changeData();

    chart.render();
  }

  changeData(): void {
    const { _chart, height, padding, mask, titleMap, position, colorMap, borderWidth, maxAxis } = this;
    let data = [...this.data()];
    if (!_chart || data.length <= 0) return;

    const arrAxis = [...Array(maxAxis())].map((_, index) => index + 1);

    _chart.legend({
      position: position(),
      custom: true,
      items: arrAxis.map(id => {
        const key = `y${id}`;
        return {
          id: key,
          name: titleMap()![key],
          value: key,
          marker: { style: { fill: colorMap()[key] } }
        } as Types.LegendItem;
      })
    });

    // border
    _chart.geometries.forEach((v, idx: number) => {
      v.color((colorMap() as NzSafeAny)[`y${idx + 1}`]).size(borderWidth());
    });
    _chart.height = height();
    _chart.padding = padding();

    // 转换成日期类型
    data = data
      .map(item => {
        item.time = toDate(item.time!);
        item._time = +item.time;
        return item;
      })
      .sort((a, b) => a._time - b._time);

    const max = Math.max(...arrAxis.map(id => [...data].sort((a, b) => b[`y${id}`] - a[`y${id}`])[0][`y${id}`]));
    const scaleOptions: Record<string, Types.ScaleOption> = {};
    arrAxis.forEach(id => {
      const key = `y${id}`;
      scaleOptions[key] = {
        alias: titleMap()![key],
        max,
        min: 0
      };
    });
    _chart.scale({
      time: {
        type: 'time',
        mask: mask(),
        range: [0, 1]
      },
      ...scaleOptions
    });

    const initialRange = {
      start: data[0]._time,
      end: data[data.length - 1]._time
    };
    const filterData = data.filter(val => val._time >= initialRange.start && val._time <= initialRange.end);
    _chart.changeData(filterData);
  }
}
